        return Ok(HistoryProgress::Resuming {
            batch_start,
            page_token: meta_get(&conn, "history_page_token")?,
        });
    }
    Ok(HistoryProgress::Idle {
        cursor: meta_get(&conn, "history_id")?,
    })
}

